CREATE TABLE IF NOT EXISTS voteBallots (id INT PRIMARY KEY AUTO_INCREMENT, voteId INT NOT NULL, userId INT NOT NULL, choice ENUM('yes', 'no', 'abstain') NOT NULL, weight DECIMAL(10, 2) DEFAULT 1, votedAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_vote_ballot (voteId));
CREATE TABLE IF NOT EXISTS resolutions (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, meetingId INT, title VARCHAR(255) NOT NULL, description TEXT, status ENUM('draft', 'approved', 'rejected', 'executed') DEFAULT 'draft', requiresSignature BOOLEAN DEFAULT true, createdBy INT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_org_resolution (organizationId));
CREATE TABLE IF NOT EXISTS signatures (id INT PRIMARY KEY AUTO_INCREMENT, documentId INT NOT NULL, resolutionId INT, userId INT NOT NULL, signatureData LONGTEXT, signedAt DATETIME DEFAULT CURRENT_TIMESTAMP, status ENUM('pending', 'signed', 'rejected') DEFAULT 'pending', createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_doc_signature (documentId));

